-- Brazil milestone translations (ES/DE/FR)

INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('br-nfe-established', 'es', 'Se establece el sistema NF-e, alcanzando una adopción casi universal', 'Brasil fue pionero en la facturación electrónica de modelo de compensación en América Latina — las mercancías no pueden enviarse legalmente sin una NF-e autorizada por la SEFAZ.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('br-nfe-established', 'de', 'Das NF-e-System wird etabliert und erreicht nahezu universelle Verbreitung', 'Brasilien war Vorreiter der Clearing-Modell-E-Rechnungsstellung in Lateinamerika — Waren dürfen ohne eine von der SEFAZ autorisierte NF-e nicht rechtmäßig versandt werden.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('br-nfe-established', 'fr', 'Le système NF-e est établi, atteignant une adoption quasi universelle', 'Le Brésil a été pionnier de la facturation électronique à modèle de contrôle en Amérique latine — les marchandises ne peuvent légalement être expédiées sans une NF-e autorisée par la SEFAZ.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('br-nfse-mei-2023', 'es', 'NFS-e obligatoria para MEI (microempresarios)', 'Originalmente prevista para el 3 de abril de 2023, esto incorporó a las empresas formales más pequeñas de Brasil al reporte estructurado de facturas de servicios a través del emergente marco nacional NFS-e.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('br-nfse-mei-2023', 'de', 'NFS-e für MEI (Kleinstunternehmer) verpflichtend', 'Ursprünglich für den 3. April 2023 vorgesehen, brachte dies Brasiliens kleinste formelle Unternehmen in die strukturierte Dienstleistungsrechnungsmeldung über das aufkommende nationale NFS-e-Rahmenwerk.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('br-nfse-mei-2023', 'fr', 'NFS-e obligatoire pour les MEI (micro-entrepreneurs)', 'Initialement prévu pour le 3 avril 2023, cela a fait entrer les plus petites entreprises formelles du Brésil dans la déclaration structurée de factures de services via le cadre national NFS-e émergent.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('br-nt-2025-002-2024', 'es', 'Se publica la Nota Técnica 2025.002', 'Define los códigos fiscales CST para los tres nuevos impuestos al consumo — CBS, IBS y el Impuesto Selectivo (IS) — e inicia el largo proceso de actualización de los diseños XML de NF-e/NFC-e para la reforma.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('br-nt-2025-002-2024', 'de', 'Technische Mitteilung 2025.002 veröffentlicht', 'Definiert die CST-Steuercodes für die drei neuen Verbrauchsteuern — CBS, IBS und die Selektivsteuer (IS) — und beginnt den langen Prozess der Aktualisierung der NF-e/NFC-e-XML-Layouts für die Reform.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('br-nt-2025-002-2024', 'fr', 'Publication de la note technique 2025.002', 'Définit les codes fiscaux CST pour les trois nouvelles taxes à la consommation — CBS, IBS et la taxe sélective (IS) — et lance le long processus de mise à jour des formats XML NF-e/NFC-e pour la réforme.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('br-lei-complementar-2025', 'es', 'Se promulga la Lei Complementar 214/2025', 'Instituye formalmente el IBS, el CBS y el Impuesto Selectivo, sustituyendo al PIS, COFINS, IPI, ICMS e ISS bajo un modelo de IVA dual — el fundamento legal de todo lo que sigue.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('br-lei-complementar-2025', 'de', 'Lei Complementar 214/2025 erlassen', 'Führt formell IBS, CBS und die Selektivsteuer ein und ersetzt PIS, COFINS, IPI, ICMS und ISS im Rahmen eines dualen Mehrwertsteuermodells — die rechtliche Grundlage für alles Weitere.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('br-lei-complementar-2025', 'fr', 'Promulgation de la Lei Complementar 214/2025', 'Institue formellement l''IBS, la CBS et la taxe sélective, remplaçant PIS, COFINS, IPI, ICMS et ISS dans le cadre d''un modèle de TVA duale — le fondement juridique de tout ce qui suit.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('br-test-env-2025', 'es', 'Se abre el entorno de pruebas para los nuevos códigos fiscales', 'Las empresas pueden probar los nuevos códigos CST y los campos CBS/IBS/IS en los servidores de homologación de la SEFAZ antes de la puesta en marcha.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('br-test-env-2025', 'de', 'Testumgebung für neue Steuercodes wird eröffnet', 'Unternehmen können die neuen CST-Codes und CBS/IBS/IS-Felder auf den Homologationsservern der SEFAZ vor dem Go-Live testen.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('br-test-env-2025', 'fr', 'Ouverture de l''environnement de test pour les nouveaux codes fiscaux', 'Les entreprises peuvent tester les nouveaux codes CST et les champs CBS/IBS/IS sur les serveurs d''homologation de la SEFAZ avant la mise en service.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('br-nt-v133-postpone-2025', 'es', 'La NT 2025.002 v1.33 pospone el bloqueo de validación estricta', 'La regla que rechazaría las facturas sin los campos IBS/CBS se marca como "implementación futura" en lugar de aplicarse de inmediato — una relajación técnica, pero explícitamente no una exención legal.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('br-nt-v133-postpone-2025', 'de', 'NT 2025.002 v1.33 verschiebt die strikte Validierungssperre', 'Die Regel, die Rechnungen ohne IBS/CBS-Felder ablehnen würde, wird als "künftige Umsetzung" markiert statt sofort durchgesetzt — eine technische Lockerung, aber ausdrücklich keine rechtliche Befreiung.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('br-nt-v133-postpone-2025', 'fr', 'La NT 2025.002 v1.33 reporte le blocage de validation strict', 'La règle qui rejetterait les factures sans champs IBS/CBS est marquée « mise en œuvre future » plutôt qu''appliquée immédiatement — un assouplissement technique, mais explicitement pas une exemption légale.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('br-fields', 'es', 'Campos CBS/IBS requeridos en NF-e/NFC-e/NFS-e (tasas de prueba)', 'A medida que comienza la reforma fiscal de doble IVA de Brasil, los documentos fiscales electrónicos deben incluir los nuevos campos CBS e IBS a tasas de prueba (0,9% / 0,1%) — sin impacto financiero todavía, pero la obligación legal de incluir los datos ya se aplica.', '["Actualice los diseños de facturación a la Nota Técnica 2025.002-RTC (última versión)", "Pruebe en el entorno de homologación de la SEFAZ antes de la puesta en marcha", "Los contribuyentes de Simples Nacional / MEI tienen un plazo extendido hasta 2027"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('br-fields', 'de', 'CBS/IBS-Felder auf NF-e/NFC-e/NFS-e erforderlich (Testsätze)', 'Mit Beginn von Brasiliens dualer Umsatzsteuerreform müssen elektronische Steuerdokumente die neuen CBS- und IBS-Felder mit Testsätzen (0,9 % / 0,1 %) enthalten — noch ohne finanzielle Auswirkung, aber die gesetzliche Pflicht zur Angabe der Daten gilt bereits.', '["Aktualisieren Sie Rechnungslayouts auf Technische Mitteilung 2025.002-RTC (neueste Version)", "Testen Sie in der Homologationsumgebung der SEFAZ vor dem Go-Live", "Simples-Nacional-/MEI-Steuerpflichtige haben eine verlängerte Frist bis 2027"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('br-fields', 'fr', 'Champs CBS/IBS requis sur NF-e/NFC-e/NFS-e (taux de test)', 'Alors que débute la réforme fiscale de double TVA du Brésil, les documents fiscaux électroniques doivent inclure les nouveaux champs CBS et IBS à des taux de test (0,9 % / 0,1 %) — sans impact financier pour l''instant, mais l''obligation légale d''inclure ces données s''applique déjà.', '["Mettez à jour les formats de facturation vers la note technique 2025.002-RTC (dernière version)", "Testez dans l''environnement d''homologation de la SEFAZ avant la mise en service", "Les contribuables Simples Nacional / MEI disposent d''un calendrier prolongé jusqu''en 2027"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('br-validate', 'es', 'Comienza la validación de campos CBS/IBS — riesgo de rechazo', 'Los sistemas de autorización comienzan a validar rigurosamente los campos CBS/IBS; las facturas con datos faltantes o inconsistentes corren el riesgo de rechazo automático.', '["Audite la salida de facturas en busca de grupos de datos CBS/IBS/IS completos y consistentes", "Resuelva rápidamente cualquier rechazo — las facturas bloqueadas detienen el movimiento de mercancías"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('br-validate', 'de', 'CBS/IBS-Feldvalidierung beginnt — Ablehnungsrisiko', 'Die Autorisierungssysteme beginnen mit der strikten Validierung der CBS/IBS-Felder; Rechnungen mit fehlenden oder inkonsistenten Daten riskieren eine automatische Ablehnung.', '["Prüfen Sie die Rechnungsausgabe auf vollständige, konsistente CBS/IBS/IS-Datengruppen", "Beheben Sie Ablehnungen schnell — blockierte Rechnungen stoppen den Warenverkehr"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('br-validate', 'fr', 'Début de la validation des champs CBS/IBS — risque de rejet', 'Les systèmes d''autorisation commencent à valider rigoureusement les champs CBS/IBS ; les factures avec des données manquantes ou incohérentes risquent un rejet automatique.', '["Auditez la sortie des factures pour des groupes de données CBS/IBS/IS complets et cohérents", "Résolvez rapidement tout rejet — les factures bloquées arrêtent le mouvement des marchandises"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('br-mandatory', 'es', 'Obligación legal completa de reporte para el Régimen Fiscal General', 'Bajo la Nota Técnica 2025.002-RTC v1.40, los contribuyentes del Régimen Fiscal General deben reportar los grupos IBS y CBS en NF-e y NFC-e con pleno efecto legal.', '["Confirme que su proveedor de ERP/facturación electrónica ha completado las actualizaciones de esquema requeridas", "Concilie los datos de CBS/IBS reportados con sus registros contables antes de la aplicación total"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('br-mandatory', 'de', 'Volle gesetzliche Meldepflicht für das allgemeine Steuersystem', 'Gemäß der Technischen Mitteilung 2025.002-RTC v1.40 müssen Steuerpflichtige im allgemeinen Steuersystem die IBS- und CBS-Gruppen in NF-e und NFC-e mit voller Rechtswirkung melden.', '["Bestätigen Sie, dass Ihr ERP-/E-Rechnungsanbieter die erforderlichen Schema-Updates abgeschlossen hat", "Gleichen Sie gemeldete CBS/IBS-Daten mit Ihren Buchhaltungsunterlagen vor der vollständigen Durchsetzung ab"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('br-mandatory', 'fr', 'Obligation légale complète de déclaration pour le régime fiscal général', 'En vertu de la note technique 2025.002-RTC v1.40, les contribuables du régime fiscal général doivent déclarer les groupes IBS et CBS dans NF-e et NFC-e avec pleine portée légale.', '["Confirmez que votre fournisseur ERP/facturation électronique a terminé les mises à jour de schéma requises", "Rapprochez les données CBS/IBS déclarées avec vos registres comptables avant l''application complète"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('br-full-migration-2033', 'es', 'Comienza la recaudación de CBS/IS; la migración completa concluye en 2033', 'La recaudación real bajo el CBS y el Impuesto Selectivo comienza en 2027, con los impuestos heredados (PIS, COFINS, IPI, ICMS, ISS) eliminados por completo para 2033 — esta es una transición genuinamente plurianual, no una fecha única de cambio.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('br-full-migration-2033', 'de', 'CBS/IS-Erhebung beginnt; vollständige Migration bis 2033 abgeschlossen', 'Die tatsächliche Steuererhebung im Rahmen von CBS und der Selektivsteuer beginnt 2027, wobei die Altsteuern (PIS, COFINS, IPI, ICMS, ISS) bis 2033 vollständig auslaufen — dies ist ein echter mehrjähriger Übergang, kein einmaliger Stichtag.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('br-full-migration-2033', 'fr', 'Début de la collecte CBS/IS ; la migration complète s''achève en 2033', 'La collecte fiscale effective sous CBS et la taxe sélective commence en 2027, les taxes héritées (PIS, COFINS, IPI, ICMS, ISS) étant complètement supprimées d''ici 2033 — il s''agit d''une transition véritablement pluriannuelle, pas d''une date de bascule unique.', '[]');
